function openVision(){const overlay=$('#visionOverlay');if(!overlay)return;unlockSpeechAudio();overlay.hidden=false;document.body.classList.add('vision-open');if(!visionStream)startVisionCamera();$('#liveVisionButton').classList.add('active');$('#visionHud').classList.toggle('collapsed',visionCollapsed)}
function closeVision(){visionAnalysisGeneration++;const overlay=$('#visionOverlay');if(overlay)overlay.hidden=true;document.body.classList.remove('vision-open');$('#liveVisionButton')?.classList.remove('active');if(visionRecognition){try{visionRecognition.stop()}catch{}visionRecognition=null}visionQueryActive=false;stopVisionSpeech();stopVisionCamera()}
function captureVisionFrame(){const video=$('#visionVideo');if(!visionStream||!video||video.readyState<2)throw new Error('Camera is not ready yet. Wait for the live preview, then retry.');const scale=Math.min(1,800/video.videoWidth,800/video.videoHeight),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(video.videoWidth*scale));canvas.height=Math.max(1,Math.round(video.videoHeight*scale));const ctx=canvas.getContext('2d',{alpha:false});ctx.drawImage(video,0,0,canvas.width,canvas.height);const image=canvas.toDataURL('image/jpeg',0.65);if(image.length>5_600_000)throw new Error('Compressed snapshot is too large to send. Retry with a simpler camera view.');return image}
async function analyzeVisionPrompt(prompt='Describe the camera view in detail.',{voiceQuery=false}={}){const generation=++visionAnalysisGeneration;stopVisionSpeech();let image;try{image=captureVisionFrame()}catch(e){toast(e.message);return}stopSpeakingOnly();unlockSpeechAudio();const turn={user:'📷 Live Vision · '+prompt,assistant:'',pending:true,vision:true};activeHistory.push(turn);renderChat();try{const result=await post('/api/vision/analyze',{image,prompt,mode:personaMode,voiceQuery});if(!result.assistant?.trim())throw new Error('Vision analysis returned no answer.');turn.assistant=result.assistant;turn.model=result.model;turn.pending=false;if(connection.publicMode){state.chats.unshift({id:crypto.randomUUID(),user:turn.user,assistant:turn.assistant,model:turn.model,mode:personaMode,createdAt:result.createdAt||new Date().toISOString()});state.chats=state.chats.slice(0,50);localStorage.setItem(publicStorageKey('chats'),JSON.stringify(state.chats))}else state.chats.unshift({id:crypto.randomUUID(),user:turn.user,assistant:turn.assistant,model:turn.model,mode:personaMode,createdAt:result.createdAt||new Date().toISOString()});if(generation===visionAnalysisGeneration&&!$('#visionOverlay')?.hidden)speakSceneDescription(turn.assistant)}catch(e){turn.pending=false;turn.error=e.message}finally{renderChat();renderHistory();}}
function askVisionByVoice(){if(visionQueryActive){try{visionRecognition?.stop()}catch{}return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('Voice queries are not supported in this browser.');unlockSpeechAudio();visionQueryActive=true;if(recognition){try{recognition.stop()}catch{}}const button=$('#visionVoice');button?.classList.add('listening');button?.setAttribute('aria-pressed','true');if(button)button.innerHTML='<span>●</span> Listening…';visionRecognition=new SR();visionRecognition.lang='en-IN';visionRecognition.interimResults=false;visionRecognition.continuous=false;visionRecognition.onresult=e=>{const prompt=e.results?.[0]?.[0]?.transcript?.trim();if(prompt)analyzeVisionPrompt(prompt,{voiceQuery:true})};visionRecognition.onerror=e=>{if(e.error!=='no-speech')toast('Voice query could not be captured. Check microphone permission.');};visionRecognition.onend=()=>{visionQueryActive=false;visionRecognition=null;button?.classList.remove('listening');button?.setAttribute('aria-pressed','false');if(button)button.innerHTML='<span>🎙</span> Voice Query';if(voiceMode)startRecognition()};try{visionRecognition.start()}catch{visionQueryActive=false;toast('Could not start voice input.')}}
function bindVision(){const open=$('#liveVisionButton'),hud=$('#visionHud'),handle=$('#visionDragHandle');if(open.dataset.bound)return;open.dataset.bound='true';open.onclick=openVision;$('#visionClose').onclick=closeVision;$('#visionCloseControl').onclick=closeVision;$('#visionAnalyze').onclick=()=>analyzeVisionPrompt('Provide an exhaustive, item-by-item description of the scene. Identify visible objects, text, condition, relationships, context, and practical details. Clearly distinguish observation from inference.');$('#visionVoice').onclick=askVisionByVoice;$('#visionStopSpeaking').onclick=stopVisionSpeech;$('#visionSwitch').onclick=()=>{stopVisionSpeech();visionFacing=visionFacing==='environment'?'user':'environment';startVisionCamera()};$('#visionCollapse').onclick=()=>{visionCollapsed=!visionCollapsed;hud.classList.toggle('collapsed',visionCollapsed);$('#visionCollapse').textContent=visionCollapsed?'+':'−';$('#visionCollapse').setAttribute('aria-label',visionCollapsed?'Expand vision window':'Collapse vision window')};let drag=null;handle.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const rect=hud.getBoundingClientRect();drag={x:e.clientX-rect.left,y:e.clientY-rect.top};handle.setPointerCapture(e.pointerId)});handle.addEventListener('pointermove',e=>{if(!drag)return;const bounds=$('#visionOverlay').getBoundingClientRect();hud.style.right='auto';hud.style.bottom='auto';hud.style.left=Math.max(8,Math.min(bounds.width-hud.offsetWidth-8,e.clientX-bounds.left-drag.x))+'px';hud.style.top=Math.max(8,Math.min(bounds.height-100,e.clientY-bounds.top-drag.y))+'px';hud.style.transform='none'});handle.addEventListener('pointerup',()=>drag=null);handle.addEventListener('pointercancel',()=>drag=null)}
function renderChat(){
  try{personaMode=localStorage.getItem('manas-mode')||personaMode}catch{}
  const renderMessage=(role,text,model,sources=[],turn=null)=>{
    const user=role==='user';const attachments=user&&turn?.displayAttachments?.length?`<div class="sent-attachments">${turn.displayAttachments.map(x=>x.previewUrl?`<img src="${esc(x.previewUrl)}" alt="${esc(x.name)}">`:`<span>📎 ${esc(x.name)}</span>`).join('')}</div>`:'';const images=!user?(turn?.imageUrls||(turn?.imageUrl?[turn.imageUrl]:[])).filter(url=>typeof url==='string'&&/^\/api\/images\/generated\/[a-f0-9-]+$/i.test(url)).map((url,i)=>`<figure class="generated-image"><img src="${esc(url)}" alt="Generated image ${i+1}: ${esc(turn.imagePrompt||'your prompt')}" loading="${i?'lazy':'eager'}"><div class="generated-image-actions"><a href="${esc(url)}?download=1" download="manas-image-${i+1}" title="Download image">📥 Download</a><button type="button" data-image-preview="${i}" data-image-url="${esc(url)}" data-image-alt="${esc(turn.imagePrompt||'Generated image')}" title="View full size">🔍 View</button></div></figure>`).join(''):'';const generatedImage=images?`<div class="generated-gallery">${images}</div>`:'';
    const links=!user&&sources?.length?`<div class="source-list"><strong>Sources</strong>${sources.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title||x.url)}</a>`).join('')}</div>`:'';
    const iot= !user&&turn?.iot?`<div class="iot-card"><strong>⌁ Local device bridge</strong>${(turn.iot.devices||[]).length?(turn.iot.devices||[]).map(d=>`<span>${esc(d.device)} · ${esc(d.state)}${d.color?' · '+esc(d.color):''}</span>`).join(''):'<span>No device state recorded.</span>'}<small>Local state only · no hardware acknowledgement</small></div>`:'';
    return `<div><div class="msg-meta">${user?'YOU':('MANAS'+(model?' · '+esc(model):''))}</div><div class="message ${user?'user':''}"><div class="msg-avatar">${user?(connection.publicMode?'•':'S'):'✳'}</div><div><div class="bubble">${esc(text)}</div>${attachments}${generatedImage}${links}${iot}</div></div></div>`
  };
  const log=activeHistory.map((turn,index)=>{
    let rows='';
    if(turn.user)rows+=renderMessage('user',turn.user,'',[],turn);
    if(turn.assistant)rows+=renderMessage('assistant',turn.assistant,turn.model,turn.sources,turn);
    if(turn.pending&&!turn.assistant)rows+=`<div class="message"><div class="msg-avatar">✳</div><div class="${turn.imagePending?'image-generation-card':'bubble thinking'}">${turn.imagePending?'<span class="image-generation-orb">✧</span><strong>Generating your visual…</strong><small>Rendering '+esc(turn.imageCount||1)+' unique variation'+((turn.imageCount||1)>1?'s':'')+'</small>':'<span class="thinking-dots">•••</span> Neural response in progress…'}</div></div>`;
    if(turn.error)rows+=`<div class="error-box chat-error" role="alert">AI reply failed: ${esc(turn.error)}<br><button class="subtle-button" data-retry="${index}">↻ Retry response</button></div>`;
    return rows
  }).join('');
  page.innerHTML=`<section class="core-intro"><div class="core-tag"><i></i> PERSONAL INTELLIGENCE CORE</div><h1>MANAS <span>CONVERSATIONAL ENGINE</span></h1><p>Secure local context · live reasoning stream · voice-ready interface</p></section><div class="chat-log" id="chatFeed" aria-live="polite">${log}</div>${composer()}`;
  const busy=activeHistory.some(x=>x.pending);
  $('#userMessage').disabled=busy;$('#sendBtn').disabled=busy;
  if(busy)$('#sendBtn').textContent='Waiting…';
  $('#sendBtn').onclick=sendChat;
  $('#userMessage').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChat()}};
  document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>retryChat(Number(b.dataset.retry)));
  page.querySelectorAll('[data-image-preview]').forEach(b=>b.onclick=()=>openImageViewer(b.dataset.imageUrl,b.dataset.imageAlt));
  $('#assistantMode').onchange=e=>{personaMode=e.target.value;localStorage.setItem('manas-mode',personaMode);syncPersonaPills()};
  syncPersonaPills();
  $('#voiceToggleBtn').onclick=toggleVoiceMode;$('#stopVoiceBtn').onclick=stopVoice;bindComposerTools();bindCanvas();updateMicButtons();
  scrollTo(0,document.body.scrollHeight)
}
function syncPersonaPills(){document.querySelectorAll('.persona-pill').forEach(button=>button.classList.toggle('active',button.dataset.mode===personaMode))}
function sendMessage(){return sendChat()}
async function streamChat(data,onToken){const r=await fetch('/api/chat/stream',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(d.error||`Request failed (${r.status})`)}if(!r.body)throw Error('Streaming is not available in this browser. Retry the request.');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',result=null;while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let boundary;while((boundary=buffer.indexOf('\n\n'))>=0){const event=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);for(const line of event.split(/\r?\n/)){if(!line.startsWith('data:'))continue;let d;try{d=JSON.parse(line.slice(5).trim())}catch{continue}if(d.error)throw Error(d.error);if(d.token)onToken(d.token);if(d.done)result=d}}}if(!result)throw Error('The AI connection ended before a complete reply arrived. Retry the request.');return result}
async function submitChatTurn(turn,index){if(turn.pending||turn.assistant||activeHistory.some(x=>x.pending))return;stopSpeakingOnly();turn.pending=true;turn.assistant='';turn.error='';renderChat();try{await memoryRefresh.catch(()=>{});const d=await streamChat({text:turn.user,history:activeHistory.slice(0,index),mode:personaMode,memory:connection.publicMode?memoryFacts:[],attachments:turn.attachmentsPayload||[]},piece=>{turn.assistant+=piece;renderChat()});if(!d.assistant?.trim())throw Error('The server returned no AI reply. Please retry.');turn.assistant=d.assistant;turn.model=d.model;turn.sources=d.sources||[];turn.iot=d.iot||null;delete turn.error;if(connection.publicMode){state.chats.unshift({...d});state.chats=state.chats.slice(0,50);localStorage.setItem(publicStorageKey('chats'),JSON.stringify(state.chats))}else state.chats.unshift(d);if(voiceMode)speak(d.assistant);const preview=extractPreviewCode(d.assistant);if(preview)setTimeout(()=>openCanvas(preview),0);const completed=activeHistory.filter(x=>x.assistant).length;if(completed>0&&completed%6===0&&completed!==lastMemoryRefresh){lastMemoryRefresh=completed;memoryRefresh=refreshMemory(activeHistory)}}catch(e){delete turn.assistant;turn.error=e.message}finally{turn.pending=false;renderChat();renderHistory();if(wakeEnabled)setTimeout(startWakeRecognition,500)}}
async function submitImageTurn(turn,index,prompt,count=1){if(turn.pending||turn.assistant||activeHistory.some(x=>x.pending))return;turn.pending=true;turn.imagePending=true;turn.imageCount=count;turn.error='';turn.imagePrompt=prompt;renderChat();try{const result=await post('/api/images/create',{prompt,count});turn.imageUrls=(result.images||[]).map(x=>x.url).filter(Boolean);if(!turn.imageUrls.length)throw new Error('Image service returned no pictures.');turn.assistant='Here are your generated images!';turn.model='Pollinations Flux';if(result.error)toast('Some image variations were unavailable; showing the ones that completed.');const entry={id:crypto.randomUUID(),user:turn.user,assistant:turn.assistant,model:turn.model,mode:personaMode,imageUrls:turn.imageUrls,imagePrompt:prompt,createdAt:new Date().toISOString()};state.chats.unshift(entry);if(connection.publicMode){state.chats=state.chats.slice(0,50);localStorage.setItem(publicStorageKey('chats'),JSON.stringify(state.chats))}delete turn.error;if(voiceMode)speak(turn.assistant)}catch(e){delete turn.assistant;turn.error=e.message}finally{turn.pending=false;turn.imagePending=false;renderChat();renderHistory()}}
async function submitResearchTurn(turn,url){turn.pending=true;renderChat();try{const result=await post('/api/agent/research',{url,question:turn.user});turn.assistant=result.assistant;turn.model='Manas Research';turn.sources=[{url:result.url,title:result.title}];if(voiceMode)speak(turn.assistant);state.chats.unshift({id:crypto.randomUUID(),user:turn.user,assistant:turn.assistant,model:turn.model,mode:personaMode,sources:turn.sources,createdAt:result.createdAt});if(connection.publicMode){state.chats=state.chats.slice(0,50);localStorage.setItem(publicStorageKey('chats'),JSON.stringify(state.chats))}}catch(e){turn.error=e.message}finally{turn.pending=false;renderChat();renderHistory()}}
async function sendChat(){const input=$('#userMessage'),text=input.value.trim();if(activeHistory.some(x=>x.pending))return;const imageRequest=parseImageIntent(text,createImageRequested);if(createImageRequested&&!text)return toast('Describe the image you want to generate.');if(text&&visionStream&&!imageRequest&&!pendingUploads.length&&/(what\s+(?:is|do you see)|what do you see|explain what you see|describe what you see|what brand is this|what is written here|what .*written|read (?:the )?(?:text|label|sign)|how do i fix this item|what(?:'s| is) in (?:the )?camera)/i.test(text)){input.value='';stopSpeakingOnly();return analyzeVisionPrompt(text)}if(!text&&!imageRequest&&!pendingUploads.length)return;if(imageRequest){if(imageRequest.limited)toast('This request is capped at 4 images. You can generate more in another request.');if(pendingUploads.length)return toast('Remove selected files before starting image generation.');if(!imageRequest.prompt)return toast('Describe what you want to see in the generated image.');stopSpeakingOnly();createImageRequested=false;input.value='';const menu=$('#actionMenu');if(menu)menu.hidden=true;const turn={user:text||`Create image: ${imageRequest.prompt}`,imagePrompt:imageRequest.prompt,imageCount:imageRequest.count};activeHistory.push(turn);return submitImageTurn(turn,activeHistory.length-1,imageRequest.prompt,imageRequest.count)}if(!text)return toast('Add a question or instruction with your attachment.');stopSpeakingOnly();const payload=pendingUploads.map(x=>x.payload).filter(Boolean);if(pdfChunks.length){const context=retrievePdfContext(text);if(context)payload.push({name:'PDF session index',kind:'text',text:`Relevant passages from locally indexed PDF files (page labels are source citations):\n${context}`})}const display=pendingUploads.map(x=>({name:x.name,kind:x.kind==='pdf-index'?'pdf':x.kind,previewUrl:x.kind==='image'?x.previewUrl:''}));const turn={user:text,attachmentsPayload:payload,displayAttachments:display};pendingUploads=[];createImageRequested=false;input.value='';const menu=$('#actionMenu');if(menu)menu.hidden=true;activeHistory.push(turn);renderAttachmentPreview();await submitChatTurn(turn,activeHistory.length-1)}
async function retryChat(index){const turn=activeHistory[index];if(!turn||turn.pending||turn.assistant)return;if(turn.imagePrompt)return submitImageTurn(turn,index,turn.imagePrompt,turn.imageCount||1);await submitChatTurn(turn,index)}function renderHistory(){const list=$('#history');list.innerHTML=state.chats.slice().reverse().slice(-9).reverse().map((c,i)=>`<button data-h="${esc(c.id)}">${esc(c.user.slice(0,29)||'Conversation')}</button>`).join('');list.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{const c=state.chats.find(x=>x.id===b.dataset.h);if(c){activeHistory=[{user:c.user,assistant:c.assistant,model:c.model,sources:c.sources||[],iot:c.iot||null,imageUrls:c.imageUrls||[],imagePrompt:c.imagePrompt}];setView('chat')}})}
function renderInbox(){page.innerHTML=`<div class="section-heading"><div><div class="eyebrow">MESSAGES & EMAIL</div><h1>Make sense of it all.</h1><p>Paste a message you choose to share. Your phone keeps control.</p></div><span class="status-tag tag-amber">Email · Not connected</span></div><div class="card"><h3>Analyze a message</h3><p>WhatsApp, SMS, iMessage, or email. Copy only what you want analyzed; nothing is read in the background.</p><div class="row"><div class="field"><label>Source</label><select id="msgSource"><option>WhatsApp</option><option>SMS / iMessage</option><option>Email</option><option>Other</option></select></div><div class="field"><label>Sender (optional)</label><input id="msgSender" placeholder="Name or address"></div></div><div class="field"><label>Message content</label><textarea id="msgText" placeholder="Paste the message or email here…"></textarea></div><button class="primary" id="analyzeBtn">✳ &nbsp; Analyze importance</button><div id="analysisError"></div></div><div class="eyebrow" style="margin:27px 0 10px">ANALYSIS HISTORY</div><div id="analysisList"></div>`;$('#analyzeBtn').onclick=analyzeMessage;renderAnalysis()}
async function analyzeMessage(){const text=$('#msgText').value.trim();if(!text)return toast('Paste some message content first.');const b=$('#analyzeBtn');b.disabled=true;b.textContent='Analyzing…';$('#analysisError').innerHTML='';try{const d=await post('/api/analyze',{text,source:$('#msgSource').value,sender:$('#msgSender').value});state.analyses.unshift(d);$('#msgText').value='';renderAnalysis()}catch(e){$('#analysisError').innerHTML=`<div class="error-box">${esc(e.message)}</div>`}finally{b.disabled=false;b.textContent='✳  Analyze importance'}}
function renderAnalysis(){const el=$('#analysisList');if(!el)return;el.innerHTML=state.analyses.length?state.analyses.map(a=>`<div class="card"><div class="row"><span class="status-tag ${a.importance==='Critical'?'tag-red':a.importance==='High'?'tag-amber':'tag-green'}">${esc(a.importance||'Unrated')}</span><span class="small-note">${esc(a.source)}${a.sender?' · '+esc(a.sender):''} · ${new Date(a.createdAt).toLocaleString()}</span></div><p class="analysis-summary">${esc(a.summary||'')}</p><p><strong>Why it matters:</strong> ${esc(a.reason||'Not provided')}</p><p><strong>Suggested action:</strong> ${esc(a.action||'Review manually')}</p>${a.deadline?`<p><strong>Deadline:</strong> ${esc(a.deadline)}</p>`:''}<p class="small-note">Confidence: ${Math.round((Number(a.confidence)||0)*100)}%</p></div>`).join(''):'<div class="empty">No analyzed messages yet.</div>'}
function renderCode(){page.innerHTML=`<div class="eyebrow">CODING WORKSPACE</div><h1 class="page-title">Let’s debug together.</h1><p class="muted">Paste code and describe the issue. AI review is real when a provider is configured. Code is reviewed as text and never executed automatically.</p><div class="card" style="margin-top:22px"><div class="row"><div class="field"><label>Filename (optional)</label><input id="codeFilename" placeholder="src/app.js"></div><div class="field"><label>Upload code file</label><input id="codeFile" type="file" accept=".js,.mjs,.ts,.tsx,.jsx,.py,.html,.css,.json,.md,.txt"></div></div><div class="field"><label>Code & context</label><textarea id="codeText" placeholder="Paste your code here…\n\nAdd the error message or what you expected to happen."></textarea></div><button class="primary" id="reviewCode">Review code ↗</button><div id="codeResult"></div></div><div class="small-note">Supported upload: text-based source files up to 1 MB. A coding assistant can suggest fixes, but tests still need to be run and verified in your own project.</div>`;$('#codeFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1e6){toast('File is larger than 1 MB.');return}$('#codeFilename').value=f.name;$('#codeText').value=await f.text()};$('#reviewCode').onclick=reviewCode}
async function reviewCode(){const code=$('#codeText').value;if(!code.trim())return toast('Paste code first.');const btn=$('#reviewCode'),out=$('#codeResult');btn.disabled=true;btn.textContent='Reviewing…';out.innerHTML='';try{const d=await post('/api/code',{filename:$('#codeFilename').value,code});out.innerHTML=`<div class="divider"></div><div class="eyebrow">AI CODE REVIEW</div><div class="bubble" style="margin-top:10px;white-space:pre-wrap">${esc(d.review)}</div><p class="small-note">Review only; the assistant did not execute or test this code.</p>`}catch(e){out.innerHTML=`<div class="error-box">${esc(e.message)}</div>`}finally{btn.disabled=false;btn.textContent='Review code ↗'}}
function renderTasks(){page.innerHTML=`<div class="eyebrow">YOUR DAY, A LITTLE LIGHTER</div><h1 class="page-title">Tasks & reminders</h1><p class="muted">A simple local list, stored on this device.</p><div class="card" style="margin-top:22px"><div class="row"><div class="field" style="flex:3"><label>What needs doing?</label><input id="taskTitle" placeholder="e.g. Call the dentist"></div><div class="field"><label>Due date (optional)</label><input id="taskDue" type="date"></div><button class="primary" id="addTask" style="align-self:end;margin-bottom:14px">Add task</button></div><div id="taskList"></div></div>`;$('#addTask').onclick=addTask;renderTaskList()}
function renderTaskList(){const el=$('#taskList');if(!el)return;el.innerHTML=state.tasks.length?state.tasks.map(t=>`<div class="task-item ${t.done?'done':''}"><input type="checkbox" data-done="${t.id}" ${t.done?'checked':''}><span class="task-name">${esc(t.title)}</span>${t.due?`<span class="task-due">${esc(t.due)}</span>`:''}<button class="delete-task" data-del="${t.id}" aria-label="Delete task">×</button></div>`).join(''):'<div class="empty">No tasks yet. Add one above.</div>';el.querySelectorAll('[data-done]').forEach(x=>x.onchange=async()=>{try{await api('/api/tasks/'+x.dataset.done,{method:'PATCH',body:JSON.stringify({done:x.checked})});const t=state.tasks.find(t=>t.id===x.dataset.done);if(t)t.done=x.checked;renderTaskList();updateCounts()}catch(e){toast(e.message)}});el.querySelectorAll('[data-del]').forEach(x=>x.onclick=async()=>{try{await api('/api/tasks/'+x.dataset.del,{method:'DELETE'});state.tasks=state.tasks.filter(t=>t.id!==x.dataset.del);renderTaskList();updateCounts()}catch(e){toast(e.message)}})}
async function addTask(){const title=$('#taskTitle').value.trim();if(!title)return toast('Write a task first.');try{const t=await post('/api/tasks',{title,due:$('#taskDue').value});state.tasks.unshift(t);$('#taskTitle').value='';renderTaskList();updateCounts()}catch(e){toast(e.message)}}
function renderSettings(){page.innerHTML=`<div class="eyebrow">PREFERENCES</div><h1 class="page-title">Settings & connections</h1><p class="muted">This assistant runs on your device. Configure providers in the local .env file.</p><div class="card" style="margin-top:21px"><h3>AI provider</h3><p>Local Ollama uses its native /api/chat endpoint. Cloud API keys, if configured, stay in the project .env and are never sent to the browser.</p><div class="row" style="margin-top:12px"><span>AI backend</span><span class="status-tag ${connection.ai?'tag-green':'tag-amber'}">${connection.aiMessage||'Not configured'}</span></div><p>Ollama is configured in the project .env with <code>AI_API_FORMAT=ollama</code>, <code>AI_BASE_URL=http://127.0.0.1:11434</code>, and the primary/fallback model names. Restart the server after changes.</p></div><div class="card"><h3>Integrations</h3><p>Email (Google OAuth): <span class="status-tag tag-amber">Not connected</span></p><p>WhatsApp: <span class="status-tag tag-green">Manual share / paste</span></p><p>SMS & iMessage: <span class="status-tag tag-green">Manual share / paste</span></p><p class="small-note">On iPhone, share or copy selected message text into Safari. iOS does not let a normal website silently read WhatsApp, SMS, or iMessage conversations. Email OAuth is not implemented in this build; no email account is being read.</p></div><div class="card"><h3>Privacy & access</h3><p>Chats, tasks, and message analyses are stored in the local <code>data/assistant.json</code> file. AI requests are sent to the provider you configure. Uploaded code is sent only when you select Review.</p><p>LAN access: bind to your laptop's private IP/LAN interface with <code>HOST=0.0.0.0</code> only after setting <code>ASSISTANT_PASSWORD</code> in <code>.env</code>. Allow Node.js only on your private Windows network in Firewall. Avoid public Wi-Fi.</p><button class="subtle-button" id="clearData">Delete local chats, tasks & analyses</button></div><div class="card"><h3>Voice</h3><p>Uses browser speech recognition and speech synthesis where supported. Safari support varies; microphone permission is requested by the browser.</p><button class="subtle-button" id="speakToggle">Test spoken response</button></div>`;$('#clearData').onclick=async()=>{if(!confirm('Permanently delete all locally stored conversations, tasks, and analyses?'))return;try{await api('/api/data',{method:'DELETE'});state={chats:[],tasks:[],analyses:[]};activeHistory=[];renderHistory();updateCounts();toast('Local data deleted.')}catch(e){toast(e.message)}};$('#speakToggle').onclick=()=>speak('Namaste! Voice responses are ready when your browser supports speech.');}
async function refresh(){try{connection=await api('/api/status');const el=$('#aiStatus');el.className='status-pill '+(connection.ai?'connected':'');el.innerHTML=`<i></i><span>AI ${connection.aiMessage||'not configured'}</span>`;$('#settingsDot').style.background=connection.ai?'#76c985':'#e7bf6c';document.body.classList.toggle('public-chat-only',!!connection.publicMode)}catch{}if(connection.publicMode){try{const saved=JSON.parse(localStorage.getItem(publicStorageKey('chats'))||'[]');state={chats:Array.isArray(saved)?saved:[],tasks:[],analyses:[]};memoryFacts=JSON.parse(localStorage.getItem(publicStorageKey('memory'))||'[]')}catch{state={chats:[],tasks:[],analyses:[]};memoryFacts=[]}}else try{state=await api('/api/data');const profile=await api('/api/memory');memoryFacts=profile.facts||[]}catch(e){toast(e.message)}renderHistory();updateCounts();render()}
function updateCounts(){$('#taskCount').textContent=state.tasks.filter(t=>!t.done).length||'';$('#inboxCount').textContent=state.analyses.length||''}
async function refreshMemory(conversation){if(!conversation.some(t=>t.user&&t.assistant))return;try{const d=await post('/api/memory/refresh',{conversation,facts:memoryFacts});memoryFacts=Array.isArray(d.facts)?d.facts:memoryFacts;if(connection.publicMode)localStorage.setItem(publicStorageKey('memory'),JSON.stringify(memoryFacts))}catch(e){console.warn('Memory refresh unavailable:',e.message)}}
function voiceStatus(message,error=false){const el=$('#vocalState');if(el){el.textContent=message;el.closest('.telemetry-line')?.classList.toggle('active',voiceListening||voiceSpeaking)}if(error)toast(message)}
function syncVoiceTelemetry(){const el=$('#vocalState');if(el&&!voiceErrorCode)el.textContent=voiceListening?'Listening…':voiceSpeaking?'Speaking':voiceMode?'Voice ready · tap mic':'Standby';if(el)el.closest('.telemetry-line')?.classList.toggle('active',voiceListening||voiceSpeaking)}
function updateMicButtons(listening=voiceListening){document.body.classList.toggle('voice-listening',listening);document.body.classList.toggle('voice-speaking',voiceSpeaking);const mic=$('#voiceToggleBtn'),top=$('#voiceTop');if(mic){mic.classList.toggle('active',listening);mic.setAttribute('aria-pressed',String(listening));mic.textContent=listening?'● Listening…':voiceMode?'🎙 Voice on · Tap to listen':'🎙 Voice'};if(top){top.classList.toggle('active',listening);top.setAttribute('aria-pressed',String(listening));top.textContent=listening?'●':'🎙';top.setAttribute('aria-label',listening?'Listening. Tap to stop and submit recognized speech':'Tap to speak; Manas will reply aloud')}}
function wakeChime(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ctx=wakeAudioContext||new AC();wakeAudioContext=ctx;if(ctx.state==='suspended')ctx.resume();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(660,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(990,ctx.currentTime+.11);gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.045,ctx.currentTime+.015);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.2);osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.21)}catch(e){console.debug('[wake] Chime unavailable:',e)}}
function updateWakeButton(){const button=$('#wakeWordToggle');if(!button)return;button.textContent=wakeEnabled?'Hey Manas: on':'Hey Manas: off';button.classList.toggle('active',wakeEnabled);button.setAttribute('aria-pressed',String(wakeEnabled))}
function stopWakeRecognition(){clearTimeout(wakeRestartTimer);if(wakeRecognition){const r=wakeRecognition;wakeRecognition=null;try{r.onend=null;r.stop()}catch{}}}
function startWakeRecognition(){if(!wakeEnabled||wakeRecognition||voiceListening||recognition||voiceSpeaking||visionQueryActive||activeHistory.some(t=>t.pending)||document.hidden)return;const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){wakeEnabled=false;updateWakeButton();voiceStatus('Speech recognition not supported in this browser',true);return}try{const r=new SR();wakeRecognition=r;r.lang='en-IN';r.continuous=true;r.interimResults=true;r.maxAlternatives=1;r.onresult=e=>{let text='';for(let i=e.resultIndex;i<e.results.length;i++)text+=e.results[i]?.[0]?.transcript||'';if(!/\b(?:hey\s+manas|listen\s+manas|manas)\b/i.test(text))return;document.body.classList.add('wake-burst');setTimeout(()=>document.body.classList.remove('wake-burst'),900);wakeChime();stopWakeRecognition();const command=text.replace(/^.*?\b(?:hey\s+manas|listen\s+manas|manas)\b[\s,:-]*/i,'').trim();voiceMode=true;syncVoiceTelemetry();if(command){const input=$('#userMessage');if(input)input.value=command;setTimeout(()=>sendMessage(),0)}else{voiceStatus('Hey Manas — listening for your command');setTimeout(startRecognition,350)}};r.onerror=e=>{if(['not-allowed','service-not-allowed','audio-capture'].includes(e.error)){wakeEnabled=false;updateWakeButton();voiceStatus(e.error==='audio-capture'?'No microphone was found. Check your device microphone.':'Microphone access is blocked. Allow microphone permission in browser settings.',true)}else if(e.error!=='no-speech'&&e.error!=='aborted')console.warn('[wake] SpeechRecognition error:',e.error)};r.onend=()=>{if(wakeRecognition===r)wakeRecognition=null;if(wakeEnabled&&!voiceListening&&!recognition&&!activeHistory.some(t=>t.pending))wakeRestartTimer=setTimeout(startWakeRecognition,450)};r.start();syncVoiceTelemetry()}catch(e){wakeRecognition=null;console.warn('[wake] Could not start passive listener:',e);if(wakeEnabled)wakeRestartTimer=setTimeout(startWakeRecognition,1200)}}
function toggleWakeWord(){unlockSpeechAudio();try{const AC=window.AudioContext||window.webkitAudioContext;if(AC){wakeAudioContext=wakeAudioContext||new AC();wakeAudioContext.resume()}}catch{}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Speech recognition not supported in this browser');return}wakeEnabled=!wakeEnabled;voiceMode=wakeEnabled||voiceMode;updateWakeButton();syncVoiceTelemetry();if(wakeEnabled){startWakeRecognition();toast('Hey Manas is listening while this tab stays open.')}else{stopWakeRecognition();toast('Wake word listener stopped.')}}
function cleanSpeechText(text){return String(text||'').replace(/```[\s\S]*?```/g,' ').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/https?:\/\/\S+/gi,' ').replace(/^\s*(?:[-*+•]|\d+[.)])\s*/gm,'').replace(/[*#_`~>|]/g,'').replace(/[-–—]/g,' ').replace(/\s+/g,' ').trim()}
function splitSpeechText(text,maxLength=220){const sentences=text.match(/[^.!?।]+[.!?।]+|[^.!?।]+$/gu)||[];const chunks=[];for(const sentence of sentences){let rest=sentence.trim();while(rest.length>maxLength){let cut=rest.lastIndexOf(' ',maxLength);if(cut<80)cut=rest.indexOf(' ',maxLength);if(cut<0)cut=rest.length;chunks.push(rest.slice(0,cut).trim());rest=rest.slice(cut).trim()}if(rest)chunks.push(rest)}return chunks}
function stopSpeakingOnly(){speechGeneration++;visionSpeechUtterance=null;if('speechSynthesis'in window)window.speechSynthesis.cancel();voiceSpeaking=false;document.body.classList.remove('voice-speaking');const badge=$('#visionSpeakingBadge');if(badge)badge.hidden=true;const stop=$('#visionStopSpeaking');if(stop)stop.textContent='◼ Stop Speaking';if(recognition){try{recognition.stop()}catch{}}syncVoiceTelemetry();updateMicButtons()}
function primeSpeechSynthesis(){if(!('speechSynthesis'in window))return;try{window.speechSynthesis.resume()}catch{}}
function unlockSpeechAudio(){if(!('speechSynthesis'in window)||!window.SpeechSynthesisUtterance)return;const synth=window.speechSynthesis;try{synth.resume();const silent=new window.SpeechSynthesisUtterance('');silent.volume=0;silent.rate=1;synth.speak(silent);synth.resume()}catch(e){console.warn('[voice] Could not unlock speech output:',e)}}
function speakChunks(text,{scene=false}={}){const spoken=cleanSpeechText(text);if(!spoken||!('speechSynthesis'in window)||!window.SpeechSynthesisUtterance){voiceStatus('Speech output is not supported in this browser',true);return}const chunks=splitSpeechText(spoken);if(!chunks.length)return;const synth=window.speechSynthesis,generation=++speechGeneration;visionSpeechUtterance=null;synth.cancel();primeSpeechSynthesis();voiceSpeaking=true;document.body.classList.add('voice-speaking');const badge=$('#visionSpeakingBadge'),button=$('#visionStopSpeaking');if(scene&&badge)badge.hidden=false;if(button)button.textContent='◼ Stop Speaking';syncVoiceTelemetry();updateMicButtons();const voices=synth.getVoices(),hindi=/[\u0900-\u097f]/.test(spoken),matching=voices.filter(v=>v.lang?.toLowerCase().startsWith(hindi?'hi':'en')),voice=matching.find(v=>/natural|neural|google|microsoft/i.test(v.name))||matching[0]||null;let index=0;const finish=()=>{if(generation!==speechGeneration)return;visionSpeechUtterance=null;voiceSpeaking=false;document.body.classList.remove('voice-speaking');if(badge)badge.hidden=true;if(button)button.textContent='◼ Stop Speaking';syncVoiceTelemetry();updateMicButtons();if(wakeEnabled)setTimeout(startWakeRecognition,500)};const next=()=>{if(generation!==speechGeneration)return;if(index>=chunks.length){finish();return}const utterance=new window.SpeechSynthesisUtterance(chunks[index++]);utterance.lang=hindi?'hi-IN':'en-IN';utterance.rate=1;utterance.pitch=1;if(voice)utterance.voice=voice;visionSpeechUtterance=utterance;utterance.onend=()=>setTimeout(next,0);utterance.onerror=e=>{console.warn('[voice] Speech output error:',e.error||e);setTimeout(next,0)};try{synth.speak(utterance);synth.resume()}catch(e){console.error('[voice] Could not speak response:',e);finish()}};next()}
function speakSceneDescription(text){speakChunks(text,{scene:true})}
function stopVisionSpeech(){stopSpeakingOnly()}
function stopVoice(){voiceMode=false;wakeEnabled=false;stopWakeRecognition();updateWakeButton();voiceCancelledSession=voiceSession;voiceSession++;const current=recognition;recognition=null;if(current){try{current.abort()}catch{}}voiceListening=false;voiceTranscript='';voiceErrorCode='';stopSpeakingOnly();syncVoiceTelemetry();updateMicButtons()}
function toggleVoiceMode(){if(voiceSpeaking)stopSpeakingOnly();unlockSpeechAudio();const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(recognition){try{recognition.stop()}catch{}return}voiceErrorCode='';voiceMode=true;syncVoiceTelemetry();if(!SpeechRecognition){voiceStatus('Speech recognition not supported in this browser',true);return}if(!$('#userMessage'))setView('chat');startRecognition()}
function startRecognition(){if(voiceListening||recognition||voiceQueryActive||voiceSpeaking||activeHistory.some(t=>t.pending))return;stopWakeRecognition();const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){voiceErrorCode='not-supported';voiceStatus('Speech recognition not supported in this browser',true);return}try{const current=new SpeechRecognition(),session=++voiceSession;recognition=current;voiceTranscript='';voiceErrorCode='';current.continuous=false;current.interimResults=true;current.lang='hi-IN';current.onstart=()=>{if(session!==voiceSession)return;voiceListening=true;voiceMode=true;voiceStatus('Listening…');updateMicButtons(true)};current.onresult=event=>{if(session!==voiceSession)return;const input=$('#userMessage');if(!input)return;let transcript='';for(let i=0;i<event.results.length;i++){const result=event.results[i];transcript+=result?.[0]?.transcript||''}voiceTranscript=transcript.trim();input.value=transcript;input.dispatchEvent(new Event('input',{bubbles:true}))};current.onspeechend=()=>{try{current.stop()}catch{}};current.onerror=event=>{if(session!==voiceSession)return;voiceErrorCode=event.error||'unknown';console.error('[voice] SpeechRecognition error:',event.error,event.message||'');const messages={'not-allowed':'Microphone access is blocked. Allow microphone permission in browser settings.','service-not-allowed':'Speech recognition is blocked by this browser or device.','no-speech':'No speech detected. Tap the mic and try again.','audio-capture':'No microphone was found. Check your device microphone.','network':'Speech recognition network error. Check your connection and retry.','language-not-supported':'Hindi speech recognition is unavailable in this browser.'};if(event.error!=='aborted')voiceStatus(messages[event.error]||`Speech input failed (${event.error}). Tap the mic to retry.`,true)};current.onend=()=>{if(session!==voiceSession)return;recognition=null;voiceListening=false;const input=$('#userMessage'),shouldSend=!voiceErrorCode&&!!voiceTranscript&&!!input?.value.trim();syncVoiceTelemetry();updateMicButtons(false);if(shouldSend)setTimeout(()=>sendMessage(),0);else if(wakeEnabled)setTimeout(startWakeRecognition,500)};current.start()}catch(error){recognition=null;voiceListening=false;voiceErrorCode=error?.name||'start-failed';console.error('[voice] SpeechRecognition start failed:',error);voiceStatus(error?.name==='NotAllowedError'?'Microphone access is blocked. Allow microphone permission in browser settings.':'Could not start speech recognition. Check microphone permission and try again.',true);syncVoiceTelemetry();updateMicButtons(false);if(wakeEnabled)setTimeout(startWakeRecognition,500)}}
function speak(text){speakChunks(text)}
const standardSendChat=sendChat;sendChat=async function(){const input=$('#userMessage'),text=input?.value.trim()||'',researchUrl=/\b(?:research|investigate|brief(?:ing)?|report|summari[sz]e)\b/i.test(text)?text.match(/https:\/\/[^\s<>"']+/i)?.[0]?.replace(/[),.;]+$/,''):null;if(researchUrl&&!pendingUploads.length&&!createImageRequested&&!activeHistory.some(x=>x.pending)){input.value='';const menu=$('#actionMenu');if(menu)menu.hidden=true;const turn={user:text};activeHistory.push(turn);return submitResearchTurn(turn,researchUrl)}return standardSendChat()};
document.querySelectorAll('.nav-item[data-view]').forEach(x=>x.onclick=()=>setView(x.dataset.view));
$('#newChat').onclick=()=>{if(activeHistory.length)memoryRefresh=refreshMemory(activeHistory);lastMemoryRefresh=0;activeHistory=[];pdfChunks=[];pendingUploads=pendingUploads.filter(x=>x.kind!=='pdf-index');renderAttachmentPreview();setView('chat')};
$('#menuToggle').onclick=()=>$('#sidebar').classList.add('open');
$('#closeNav').onclick=()=>$('#sidebar').classList.remove('open');
$('#voiceTop').onclick=toggleVoiceMode;
$('#wakeWordToggle').onclick=toggleWakeWord;
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopWakeRecognition();else if(wakeEnabled)startWakeRecognition()});
bindVision();
